let windowSize = 1h;

// S99: Passive Recon — 수동 정찰 로그에 기록된 표적 군집(SwarmId) ID
let S99 =
    UAVPassiveCollect_CL
    | where TimeGenerated > ago(windowSize)
    | where EventType == 'recon_scan'
    | extend Stage = 'S99', SwarmId = tostring(TargetSwarmId)
    | where isnotempty(SwarmId)
    | project TimeGenerated, Stage, SwarmId;

// S101: Leader Hijack
let S101 =
    UAVSwarmComms_CL
    | where TimeGenerated > ago(windowSize)
    | where EventType == 'leader_hijack'
    | extend Stage = 'S101', SwarmId = tostring(SwarmId)
    | where isnotempty(SwarmId)
    | project TimeGenerated, Stage, SwarmId;

// S107: 1:N Command Amplification
let S107 =
    UAVSwarmComms_CL
    | where TimeGenerated > ago(windowSize)
    | where EventType == 'cmd_amplify_1n'
    | extend Stage = 'S107', SwarmId = tostring(SwarmId)
    | where isnotempty(SwarmId)
    | project TimeGenerated, Stage, SwarmId;

// S104: Formation Scatter
let S104 =
    UAVSwarmComms_CL
    | where TimeGenerated > ago(windowSize)
    | where EventType == 'formation_scatter'
    | extend Stage = 'S104', SwarmId = tostring(SwarmId)
    | where isnotempty(SwarmId)
    | project TimeGenerated, Stage, SwarmId;

union S99, S101, S107, S104
| summarize StagesSeen = make_set(Stage), StageCount = dcount(Stage), FirstSeen = min(TimeGenerated), LastSeen = max(TimeGenerated) by SwarmId
| where StageCount >= 3
| extend CampaignType = "C24_리더참수_정찰_스푸핑_증폭_분산"
| extend StepSummary = strcat("Stages=", tostring(StagesSeen), " | First=", tostring(FirstSeen), " | Last=", tostring(LastSeen))
| extend Severity = "High"
| project FirstSeen, LastSeen, SwarmId, StagesSeen, StageCount, CampaignType, StepSummary, Severity
